mapper.select:
SELECT * FROM ( SELECT ( SELECT gjt.DESCRIPTION FROM GLD_JE_TRX gjt WHERE gjt.JE_TRX = gjtd.JE_TRX ) AS DESCRIPTION, ( SELECT cc.contract_number FROM con_contract cc WHERE cc.contract_id = gjtd.JE_SOURCE_ID ) AS CONTRACT_NUMBER, ( SELECT cc.contract_name FROM con_contract cc WHERE cc.contract_id = gjtd.JE_SOURCE_ID ) AS CONTRACT_NAME, ( SELECT cc.lease_start_date FROM con_contract cc WHERE cc.contract_id = gjtd.JE_SOURCE_ID ) AS LEASE_START_DATE, ( SELECT cc.lease_item_amount FROM con_contract cc WHERE cc.contract_id = gjtd.JE_SOURCE_ID ) AS LEASE_ITEM_AMOUNT, ( SELECT ct.transaction_num FROM csh_transaction ct WHERE gjtd.JE_TRX_ID=ct.transaction_id UNION SELECT ct.transaction_num FROM csh_transaction ct, csh_write_off cwo WHERE cwo.csh_transaction_id = ct.transaction_id and gjtd.JE_TRX_ID=cwo.write_off_id GROUP BY ct.transaction_num ) AS DOCUMENT_NUMBER, ( SELECT cwo.csh_write_off_amount AS AMOUNT FROM csh_write_off cwo WHERE gjtd.JE_TRX_ID=cwo.write_off_id UNION SELECT ct.transaction_amount AS AMOUNT FROM csh_transaction ct WHERE gjtd.JE_TRX_ID=ct.transaction_id UNION SELECT gcfi.FINANCE_INCOME AS AMOUNT FROM gld_contract_finance_income gcfi WHERE gjtd.JE_TRX_ID=gcfi.FINANCE_INCOME_ID UNION SELECT aih.total_amount AS AMOUNT FROM acr_invoice_hd aih WHERE gjtd.JE_TRX_ID=aih.invoice_hd_id ) AS JETRX_AMOUNT, gjtd.JE_TRX_ID, gjtd.JE_TRX, gjtd.JE_TRX_DTL_ID, gjtd.MSG_LOG, gjtd.LAST_UPDATE_DATE, gjtd.JE_SOURCE_ID, gjtd.JE_SOURCE_DOC, ( SELECT v.meaning FROM
v WHERE v.code = 'GLD.JE_TRX_DTL_STATUS' AND v.code_value = gjtd.STATUS ) AS STATUS FROM GLD_JE_TRX_DTL gjtd ) tab
tab.STATUS IN
#{item}
AND tab.DESCRIPTION IN
#{item}
AND tab.CONTRACT_NUMBER like concat(concat('%',#{contractNumber}),'%') OR tab.CONTRACT_NAME like concat(concat('%',#{contractNumber}),'%')
AND tab.DOCUMENT_NUMBER like concat(concat('%',#{documentNumber}),'%') OR tab.JETRX_AMOUNT = #{documentNumber}
and to_char(tab.LAST_UPDATE_DATE,'YYYY-MM-DD')>= #{lastUpdateDateFromStr}
and to_char(tab.LAST_UPDATE_DATE,'YYYY-MM-DD') <=#{lastUpdateDateToStr}
order by LAST_UPDATE_DATE desc
